'use strict';
const fs=require('fs'),path=require('path'),zlib=require('zlib');
const root=path.resolve(__dirname,'../..');
const entries=JSON.parse(zlib.inflateSync(Buffer.from('','base64')));
for(const entry of entries){if(!entry.path.startsWith('SOFIA_APP/')||entry.path.split('/').includes('..'))throw Error('Unsafe source path');const p=path.join(root,entry.path);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,entry.content);}
const p=path.join(root,'SOFIA_APP/package-lock.json'),lock=JSON.parse(fs.readFileSync(p,'utf8'));lock.version='0.3.32';lock.packages[''].version='0.3.32';fs.writeFileSync(p,JSON.stringify(lock,null,2)+'\n');
console.log('Applied 0.3.32 source changes:',entries.length+1);
